<template><div class="app-container"><el-alert title="同步日志中的原始回调载荷已加密，后台永不回显；FAILED 可重试，超过最大次数后进入 DEAD。" type="info" :closable="false" style="margin-bottom:16px"/><div class="filter-container"><el-input v-model="query.providerCode" placeholder="厂商编码" clearable style="width:180px"/><el-select v-model="query.syncStatus" clearable placeholder="状态"><el-option label="待处理" value="PENDING"/><el-option label="成功" value="SUCCESS"/><el-option label="失败" value="FAILED"/><el-option label="终止" value="DEAD"/></el-select><el-button type="primary" @click="load">查询</el-button></div><el-table v-loading="loading" :data="list" border><el-table-column prop="syncNo" label="同步编号" min-width="180"/><el-table-column prop="providerCode" label="厂商"/><el-table-column prop="deviceSn" label="设备编号" min-width="150"/><el-table-column prop="externalNo" label="外部编号" min-width="180"/><el-table-column prop="statusText" label="状态"/><el-table-column prop="retryCount" label="重试次数"/><el-table-column prop="nextRetryTime" label="下次重试" min-width="160"/><el-table-column prop="errorMessage" label="失败原因" min-width="240" show-overflow-tooltip/><el-table-column label="操作" width="90"><template slot-scope="{row}"><el-button v-if="row.syncStatus==='FAILED'||row.syncStatus==='DEAD'" type="text" @click="retry(row)">重试</el-button></template></el-table-column></el-table></div></template><script>import{getJkHealthSyncList,retryJkHealthSync}from'@/api/jkBusiness';export default{data(){return{query:{page:1,limit:20},list:[],loading:false}},created(){this.load()},methods:{rows(r){return(r&&r.list)||(r&&r.data&&r.data.list)||r.data||r||[]},load(){this.loading=true;getJkHealthSyncList(this.query).then(r=>this.list=this.rows(r)).finally(()=>this.loading=false)},retry(row){this.$confirm('确认重新处理该同步记录？').then(()=>retryJkHealthSync(row.id)).then(()=>{this.$message.success('重试完成');this.load()})}}}</script>